1	// `@goodfetch/collie` (ADRs 0090, 0095): Collie's TypeScript SDK and its `goodfetch-collie` bin. It
2	// re-exports the Collie client package, whose values (Run, Session, Page, errors) a Foxhound handler
3	// gets too, and adds the connection, which finds Collie's executable through its own platform
4	// packages and reads only `GOODFETCH_COLLIE_ENGINE_PATH` (ADR 0090).
5	export * from "@goodfetch/collie-client";
6	
7	import type {
8	  CallOptions,
9	  ConnectOptions,
10	  Connection,
11	  EngineInfo,
12	  ExplainedSetting,
13	  Identities,
14	  JSONObject,
15	  JSONValue,
16	  Run,
17	  RunView,
18	  SettingKey,
19	  StartOptions,
20	} from "@goodfetch/collie-client";
21	
22	/**
23	 * A connection to an engine, Collie's or Foxhound's (ADR 0095): the entry point (ADR 0078). Each one
24	 * is independent, and many may be open in one process. A Collie connection announces Collie in
25	 * `hello`, so a Foxhound engine accepts it too.
26	 */
27	export declare class Collie implements Connection {
28	  private constructor();
29	  /** Starts or finds the engine and completes `hello` before returning. */
30	  static connect(options?: ConnectOptions): Promise<Collie>;
31	  engine(): EngineInfo;
32	  /** The install's Saved identities (ADR 0092). */
33	  readonly identities: Identities;
34	  start(options?: StartOptions): Promise<Run>;
35	  openRun(id: string, options?: CallOptions): Promise<RunView>;
36	  /** Cancels in-flight calls, closes every Run it opened and ends every borrow; stops an Attached engine, only disconnects from a Daemon. */
37	  close(options?: CallOptions): Promise<void>;
38	  [Symbol.asyncDispose](): Promise<void>;
39	  explainSettings(keys?: readonly SettingKey[], options?: CallOptions): Promise<readonly ExplainedSetting[]>;
40	  /** The raw catalog call (ADR 0099): `params` names every value itself. */
41	  call(operation: string, params?: JSONObject, options?: CallOptions): Promise<JSONValue>;
42	}

1	// `@goodfetch/foxhound` (ADRs 0090, 0095): Foxhound's TypeScript SDK and its `goodfetch-foxhound` bin.
2	// It re-exports the Collie client package, so a handler's Page is the Page a Collie program gets,
3	// and adds Foxhound's connection, the generated layer of Foxhound's own entries and the objects only
4	// Foxhound hands out: crawls and their contexts, Datasets, Records, Exports, Hooks and Politeness.
5	// Where a name both packages export means more here (`Settings`, `SettingKey`, `TimeoutSettings`,
6	// `PolitenessSettings`, `SitePreferencesSettings`, `KnownErrorCode`, `ErrorCode`, `ConnectOptions`),
7	// Foxhound's own export, which adds its keys or values to Collie's, is the one this package gives.
8	export * from "@goodfetch/collie-client";
9	export * from "./connection.js";
10	export * from "./crawl.js";
11	export * from "./data.js";
12	export * from "./hooks.js";
13	export * from "./outcomes.js";
14	export * from "./output.js";
15	export * from "./politeness.js";
16	export * from "./run.js";
17	export * from "./settings.js";
18	// Foxhound's own exports of the names it widens, which win over the client package's.
19	export type { ConnectOptions } from "./connection.js";
20	export type { ErrorCode, KnownErrorCode } from "./outcomes.js";
21	export type { PolitenessSettings, SitePreferencesSettings } from "./politeness.js";
22	export type { SettingKey, Settings, TimeoutSettings } from "./settings.js";

1	// Foxhound's connection (ADRs 0090, 0095): `Foxhound` carries every member of `Collie` under the same
2	// names, Collie's Run start included, plus its own, so moving a program from Collie to Foxhound
3	// changes its import and its connection type only. It finds Foxhound's executable through its own
4	// platform packages and reads only `GOODFETCH_FOXHOUND_ENGINE_PATH` (ADR 0090).
5	
6	import type {
7	  CallOptions,
8	  ConnectOptions as CollieConnectOptions,
9	  Connection,
10	  EngineInfo,
11	  ExplainedSetting,
12	  Identities,
13	  JSONObject,
14	  JSONValue,
15	  Run,
16	  RunView,
17	  StartOptions,
18	} from "@goodfetch/collie-client";
19	import type { Crawl, CrawlRun, CrawlRunView, CrawlStartOptions } from "./crawl.js";
20	import type { FetchBackendHandler, SinkHandler } from "./hooks.js";
21	import type { SettingKey, Settings } from "./settings.js";
22	
23	/** Options of `Foxhound.connect()`: Collie's, Foxhound's settings, and the SDK handlers of Foxhound's own Plugin kinds (ADR 0088). */
24	export interface ConnectOptions extends Omit<CollieConnectOptions, "settings"> {
25	  /** Settings for this connection and everything opened beneath it, Foxhound's keys included. */
26	  readonly settings?: Settings;
27	  /**
28	   * Fetch backends answered by the program's own code, by the name settings choose them by (ADR
29	   * 0104; ADR 0033's SDK-handler form). The only one on the connection becomes the value of the
30	   * setting that chooses a Fetch backend, with the run-layer origin `registered`, which every other
31	   * run-layer value replaces and a lock beats; two fail `connect()` when nothing else sets the key.
32	   */
33	  readonly fetchBackends?: Readonly<Record<string, FetchBackendHandler>>;
34	  /**
35	   * Sinks answered by the program's own code, each serving the `sinks.<name>` entry of its name,
36	   * which then takes no `type` (ADRs 0103, 0104).
37	   */
38	  readonly sinks?: Readonly<Record<string, SinkHandler>>;
39	}
