41	/**
42	 * A connection to a Foxhound engine: the entry point (ADR 0078). A Collie engine refuses it at
43	 * `connect()` with `not_in_product` (ADR 0095). Each one is independent, and many may be open in
44	 * one process.
45	 */
46	export declare class Foxhound implements Connection {
47	  private constructor();
48	  /** Starts or finds the engine and completes `hello` before returning. */
49	  static connect(options?: ConnectOptions): Promise<Foxhound>;
50	  engine(): EngineInfo;
51	  /** The install's Saved identities (ADR 0092). */
52	  readonly identities: Identities;
53	  /** Collie's Run start (ADR 0102), unchanged: a Run with no crawl. */
54	  start(options?: StartOptions): Promise<Run>;
55	  openRun(id: string, options?: CallOptions): Promise<RunView>;
56	  /**
57	   * Starts a Run of the crawl from its seeds and returns once it is started; its handlers run from
58	   * then on (ADR 0102, Firecrawl's `start_crawl`). An `id` naming an existing Run behaves as
59	   * `start`'s does, the seeds and the Plan file being inputs that must match. Throws
60	   * `LabelUnhandledError` when a Label has no handler, and `LabelUnknownError` when a resumed Run
61	   * has pending requests of a Label no longer declared (ADR 0093).
62	   */
63	  startCrawl(crawl: Crawl, options: CrawlStartOptions): Promise<CrawlRun>;
64	  /** Opens a crawl's Run by its ID to read it, as `openRun` does, with its outcomes, Records and Exports. */
65	  openCrawlRun(id: string, options?: CallOptions): Promise<CrawlRunView>;
66	  /** Cancels in-flight calls, closes every Run it opened and ends every borrow; stops an Attached engine, only disconnects from a Daemon. */
67	  close(options?: CallOptions): Promise<void>;
68	  [Symbol.asyncDispose](): Promise<void>;
69	  explainSettings(keys?: readonly SettingKey[], options?: CallOptions): Promise<readonly ExplainedSetting[]>;
70	  /** The raw catalog call (ADR 0099): `params` names every value itself. */
71	  call(operation: string, params?: JSONObject, options?: CallOptions): Promise<JSONValue>;
72	}

1	// Crawl definition and handler context (ADR 0093, decided in #477).
2	// A crawl is declared by a `Crawl` value, made with no connection and no I/O: each Label is declared
3	// first, returning its typed handle, and then gets exactly one handler. A Run carries the crawl out;
4	// `Foxhound.startCrawl` starts one, and a start under the same ID resumes it (ADR 0102, run.d.ts).
5	// A handler receives one context on every fetch tier: Collie's page over the request's document,
6	// with a call that only a browser can serve escalating the request to the browser tier.
7	// Outcomes and skip reasons are in results.d.ts, the settings in settings.d.ts. Datasets, pushing and
8	// reading Records are ADR 0103's (output.d.ts).
9	
10	import type {
11	  CallOptions,
12	  EventIterator,
13	  JSONObject,
14	  Limits,
15	  Locator,
16	  Page,
17	  PageError,
18	  ProgramError,
19	  Recording,
20	  RefusedError,
21	  Response,
22	  Run,
23	  RunView,
24	  Schema,
25	  SchemaInput,
26	  SchemaOutput,
27	  Timeout,
28	  UnavailableError,
29	  ExplainedSetting,
30	} from "@goodfetch/collie-client";
31	import type { Dataset, Label, PayloadInput, PayloadOutput } from "./data.js";
32	import type {
33	  AfterResponseHook,
34	  AnyLabel,
35	  BeforeRequestHook,
36	  HookOptions,
37	  PageStageHook,
38	  RecordCommitHook,
39	  RecordHookOptions,
40	  RecordOf,
41	  UntypedRecord,
42	} from "./hooks.js";
43	import type { CrawlRequestOutcome } from "./outcomes.js";
44	import type {
45	  DatasetOptions,
46	  DatasetRecord,
47	  Export,
48	  ExportOptions,
49	  KeyField,
50	  RecordsOptions,
51	  RejectedRecord,
52	} from "./output.js";
53	import type { CrawlRunProgress, CrawlRunReport } from "./run.js";
54	import type { CrawlRunSettings, LabelSettings, SettingKey } from "./settings.js";
