56	/** A URL pattern matched in the engine: a glob, or a regular expression in the Rust `regex` syntax (ADR 0081). No predicate: every link would cross the connection. */
57	export type URLPattern = string | RegExp;
58	
59	/**
60	 * The fetch tiers of ADR 0020. `auto`, the default, learns the tier per Label on a domain by sample
61	 * comparison; any other value forces it (ADR 0023), and Provenance records that it was forced.
62	 */
63	export type FetchTier = "http" | "discovered_api" | "browser_fetch" | "light_browser" | "browser";
64	/** A tier a newer engine reports and this SDK does not know is kept as received (G3). */
65	export type ReportedFetchTier = FetchTier | (string & {});
66	
67	/** Options of declaring a Label. */
68	export interface LabelOptions<S extends Schema | undefined> {
69	  /** The Payload's schema (ADR 0082). Left out: the Label takes no Payload. */
70	  readonly payload?: S;
71	  /** Settings for this Label's requests: a scope between the Run and each request. */
72	  readonly settings?: LabelSettings;
73	  /** The scripted login step of the Sessions this Label's requests use (ADRs 0006, 0092), called with the Session's page on the login page. Setting it gives the Label a Session pool of its own. */
74	  readonly login?: (page: Page) => Promise<void>;
75	}
76	
77	/** Options of a crawl's declaration. */
78	export interface CrawlOptions {
79	  /** The scripted login step of the Run's Session pool (ADRs 0006, 0092); a Label's own `login` wins for its Sessions. */
80	  readonly login?: (page: Page) => Promise<void>;
81	}
