83	/** A Label's handler. It may return a promise; its value is ignored. */
84	export type Handler<L extends Label<unknown, unknown>> = (ctx: CrawlContext<L>) => void | Promise<void>;
85	
86	/**
87	 * A crawl's declaration: its Labels and their handlers. It needs no connection and does no I/O, so a
88	 * module may declare it when it loads. A Run is started from it, and resumed with it, since handlers
89	 * are never persisted.
90	 */
91	export declare class Crawl {
92	  constructor(options?: CrawlOptions);
93	  /**
94	   * Declares a Label and returns its typed handle. A second Label of the same name throws
95	   * `LabelDuplicateError` at once.
96	   */
97	  label(name: string, options?: LabelOptions<undefined>): Label<undefined>;
98	  label<S extends Schema>(name: string, options: LabelOptions<S> & { readonly payload: S }): Label<SchemaInput<S>, SchemaOutput<S>>;
99	  /**
100	   * Declares a Dataset and returns its typed handle (ADR 0103): there is no default Dataset, so every
101	   * push names one. A second Dataset of the same name throws `DatasetDuplicateError` at once, and a
102	   * `key` on a field the schema does not require throws `DatasetKeyInvalidError`.
103	   */
104	  dataset(name: string, options?: { readonly key?: readonly KeyField<JSONObject>[] }): Dataset<JSONObject>;
105	  dataset<S extends Schema>(name: string, options: DatasetOptions<S>): Dataset<SchemaInput<S>, SchemaOutput<S>>;
106	  /**
107	   * Attaches the Label's one handler. A second handler throws `LabelDuplicateError` at once; a Label
108	   * left without one makes the Run's start throw `LabelUnhandledError`.
109	   */
110	  handle<L extends Label<unknown, unknown>>(label: L, handler: Handler<L>): void;
111	
112	  // Hooks in code (ADR 0104): one method per stage, run in the order declared, after the Hooks
113	  // that settings name (`hooks.*`), with no integers. Scoped to `labels`, a Hook sees their
114	  // Payloads typed; left unscoped, it runs for every Label. Never persisted, like handlers.
115	
116	  /** Before each fetch of a request, retries, escalations and sample-comparison runs included: it may rewrite the URL, set headers or skip. */
117	  beforeRequest<const Ls extends readonly AnyLabel[] = readonly AnyLabel[]>(hook: BeforeRequestHook<Ls[number]>, options?: HookOptions<Ls>): void;
118	  /** After the final response, before the status rule: it may rewrite the body, mark a block or ask for a retry. */
119	  afterResponse<const Ls extends readonly AnyLabel[] = readonly AnyLabel[]>(hook: AfterResponseHook<Ls[number]>, options?: HookOptions<Ls>): void;
120	  /** Before the browser navigates: set cookies, block resources, add init scripts. Only on the `browser` and `light_browser` tiers. */
121	  beforeNavigation<const Ls extends readonly AnyLabel[] = readonly AnyLabel[]>(hook: PageStageHook<Ls[number]>, options?: HookOptions<Ls>): void;
122	  /** After the browser navigated, before the engine's own page work (consent, challenges, the expected page). Only on the `browser` and `light_browser` tiers. */
123	  afterNavigation<const Ls extends readonly AnyLabel[] = readonly AnyLabel[]>(hook: PageStageHook<Ls[number]>, options?: HookOptions<Ls>): void;
124	  /** Just before the handler, on every tier, with the handler's page: the router middleware of Crawlee's `router.use`. */
125	  pageReady<const Ls extends readonly AnyLabel[] = readonly AnyLabel[]>(hook: PageStageHook<Ls[number]>, options?: HookOptions<Ls>): void;
126	  /** Before each Record's commit: it may change, drop or reject it. Scoped to `datasets`, it sees their Record type. */
127	  beforeRecordCommit<
128	    const Ls extends readonly AnyLabel[] = readonly AnyLabel[],
129	    const Ds extends readonly Dataset<unknown, unknown>[] = readonly Dataset<UntypedRecord, unknown>[],
130	  >(hook: RecordCommitHook<Ls[number], RecordOf<Ds[number]>>, options?: RecordHookOptions<Ls, Ds>): void;
131	}
