133	/** A link `enqueueLinks` matched, as its Payload function sees it. */
134	export interface LinkInfo {
135	  readonly href: string;
136	  readonly text: string;
137	  readonly attributes: Readonly<Record<string, string>>;
138	}
139	
140	/** `enqueueLinks`'s arguments after the Label: one Payload for every link, or a function of each link returning its Payload, or `null` to skip it. */
141	export type LinkPayloadArgs<L extends Label<unknown, unknown>, O> = [PayloadInput<L>] extends [undefined]
142	  ? [options?: O]
143	  : [payload: PayloadInput<L> | ((link: LinkInfo) => PayloadInput<L> | null), options?: O];
144	
145	/** The arguments after the Label: the Payload only when the Label has one, then the options. */
146	export type PayloadArgs<L extends Label<unknown, unknown>, O> = [PayloadInput<L>] extends [undefined]
147	  ? [options?: O]
148	  : [payload: PayloadInput<L>, options?: O];
149	
150	/** A seed: a crawl request the program gives at the start, checked as an enqueue is. On a resume, the seeds must match the Run's. */
151	export interface Seed {
152	  readonly url: string;
153	  readonly label: string;
154	  /** Phantom: built only by `seed()`, so its Payload matched its Label. */
155	  readonly "~seed": true;
156	}
157	/** Builds a seed, typed as `enqueue` is. */
158	export declare function seed<L extends Label<unknown, unknown>>(url: string | URL, label: L, ...args: PayloadArgs<L, RequestShape>): Seed;
159	/** One rule of a sitemap seed: URLs matching the pattern go to the Label, one without a Payload. The first rule that matches wins. */
160	export type SitemapRule = readonly [pattern: URLPattern, label: Label<undefined>];
161	/**
162	 * Seeds from a sitemap (ADR 0093; ADR 0037's CO-10): `url` is a sitemap, or a site's robots.txt
163	 * whose `Sitemap:` lines are read. Nested sitemap indexes are followed; an entry matching no rule
164	 * is not added and is reported as `no_rule`. It widens the scope by its own host, like any seed,
165	 * and its entries are checked against the scope as enqueues are, at depth 0.
166	 */
167	export declare function sitemap(url: string | URL, rules: readonly SitemapRule[]): Seed;
168	
169	/** One crawl request of Label `L`, as its handler sees it. The engine's fields are kept apart from the Payload (ADR 0082). */
170	export interface CrawlRequest<L extends Label<unknown, unknown> = Label<undefined>> {
171	  readonly id: string;
172	  /** The URL the Frontier admitted, after its URL rules (ADR 0005). The final URL is `page.url()`. */
173	  readonly url: string;
174	  /** The request's own Label, the handle to enqueue more of the same kind (pagination). */
175	  readonly label: L;
176	  /** Parsed by the Label's schema: its output type. */
177	  readonly payload: PayloadOutput<L>;
178	  /** 0 for a seed, one more for each enqueue from a handler. */
179	  readonly depth: number;
180	  /** 1 for the first attempt. Escalations and sample-comparison runs are not retries and do not count. */
181	  readonly attempt: number;
182	}
183	
184	/** A crawl request's own method, headers and body (ADR 0093): a POST or GraphQL API is crawled page by page. */
185	export interface RequestShape {
186	  /**
187	   * `GET` by default. A crawl request is a read whatever its method, sent again on a retry, an
188	   * escalation or a sample comparison; an Effect goes through `page.request` inside `ctx.run.effect`
189	   * (ADR 0106).
190	   */
191	  readonly method?: string;
192	  readonly headers?: Readonly<Record<string, string>>;
193	  readonly body?: string | Uint8Array;
194	}
195	
196	/** Options of `enqueue`. */
197	export interface EnqueueOptions extends CallOptions, RequestShape {
198	  /** Higher first, within its domain (ADRs 0004, 0005). Default 0. */
199	  readonly priority?: number;
200	  /** Ahead of the domain's pending requests at its priority (ADR 0005). */
201	  readonly forefront?: boolean;
202	  /** The request's identity in the Frontier instead of its method, URL and body hash: a declared canonicalization, which always wins (ADR 0005). */
203	  readonly key?: string;
204	}
205	
206	/** Options of `enqueueLinks`: no `key` or `forefront`, which would give every link one identity or jump them all ahead. */
207	export interface EnqueueLinksOptions extends CallOptions {
208	  /** Higher first, within its domain (ADRs 0004, 0005). Default 0. */
209	  readonly priority?: number;
210	  /** Only links matching one of these, within the crawl's scope, which they narrow and never widen. */
211	  readonly include?: readonly URLPattern[];
212	  /** No link matching any of these. */
213	  readonly exclude?: readonly URLPattern[];
214	  /** At most this many links added: the first in document order, once `include` and `exclude` have filtered them. */
215	  readonly limit?: number;
216	}
