218	/** Why a URL was not added. A newer engine's reason is kept as received (G3). */
219	export type NotAddedReason =
220	  | "duplicate"
221	  | "out_of_scope"
222	  | "domain_policy"
223	  | "max_depth"
224	  | "max_requests"
225	  | "unsupported_scheme"
226	  | "no_link"
227	  | "no_rule"
228	  | "skipped_by_payload"
229	  | (string & {});
