231	/**
232	 * What an enqueue did: an answer, never an error (ADR 0079). From a handler, an addition is staged
233	 * with the attempt and committed with it (ADR 0003).
234	 */
235	export type Enqueued =
236	  | { readonly added: true; readonly id: string; readonly url: string }
237	  | { readonly added: false; readonly url: string; readonly reason: NotAddedReason };
238	
239	/** What `enqueueLinks` did with each element its locator matched. An element with no link is reported with `url: null` and `no_link`. */
240	export interface EnqueuedLinks {
241	  readonly added: readonly { readonly id: string; readonly url: string }[];
242	  readonly notAdded: readonly { readonly url: string | null; readonly reason: NotAddedReason }[];
243	}
