245	/**
246	 * What a handler receives, the same on every fetch tier. Every tier but `browser` serves what it
247	 * can exactly: `http` and `browser_fetch` the fetched document, `discovered_api` the document and
248	 * network waits from the JSON calls it replays, `light_browser` scripts without layout. On the
249	 * document tiers `goto`, `reload` and `page.session().newPage()` are served over the same tier
250	 * through the navigation gate (ADR 0087). A call a tier cannot serve (on the document tiers another
251	 * gesture, a popup, `evaluate`, an unanswered network wait, a screenshot, an acting AI verb; on
252	 * `light_browser`, what needs layout or pixels),
253	 * a wait for something a static document lacks, or a page failing its Session's
254	 * `session.page_check.expectedPage` (ADR 0092) ends the attempt and runs the request again in the
255	 * browser, unless `fetch.tier` forces the tier, when the call throws `BrowserRequiredError` and the
256	 * page fails with `page_check_failed`. `page.request` never escalates. A question (`count()`,
257	 * `isVisible()`) answers at once and never escalates.
258	 *
259	 * A context belongs to one attempt. Once the attempt has ended (the handler's return, `skip`, `retry`,
260	 * an escalation, the handler's timeout, a lost lease, the Run's close), every call on it throws `AttemptEndedError`. An attempt
261	 * whose handler returned commits what it staged; one that ended early discards it.
262	 */
263	export interface CrawlContext<L extends Label<unknown, unknown> = Label<undefined>> {
264	  readonly request: CrawlRequest<L>;
265	  /** Collie's page (ADR 0085), with its AI verbs, fenced by the work item's lease and journaled. `page.session()` reaches cookies. */
266	  readonly page: Page;
267	  /** The main document's final response, after redirects; its body is always kept. */
268	  readonly response: Response;
269	  /** The tier that fetched this attempt. */
270	  tier(): ReportedFetchTier;
271	  /**
272	   * The crawl's Run, bound to this attempt (ADR 0093): `addSeed` and its Key-value store's writes
273	   * through it are staged with the attempt, and its reads see them first. The program's own `run`
274	   * value writes at once.
275	   */
276	  readonly run: CrawlRun;
277	  /**
278	   * Stages a Record with this attempt (ADR 0103): it commits with the attempt, numbered in its
279	   * Dataset, or is discarded if the attempt fails or ends early (`skip`, `retry`, an escalation,
280	   * the handler's timeout, a lost lease, the Run's close), after which a push throws
281	   * `AttemptEndedError`, as `enqueue` does. Resolves once staged. A Record failing the Dataset's schema, not JSON, or lacking its key's
282	   * fields throws `RecordInvalidError` and is not staged; a Dataset of another crawl throws
283	   * `DatasetUnknownError`.
284	   */
285	  push<I>(dataset: Dataset<I, unknown>, record: NoInfer<I>, options?: CallOptions): Promise<void>;
286	  /** Adds one URL to the Frontier, checked against the crawl's scope; a Payload failing its schema throws `PayloadInvalidError`. */
287	  enqueue<L extends Label<unknown, unknown>>(url: string | URL, label: L, ...args: PayloadArgs<L, EnqueueOptions>): Promise<Enqueued>;
288	  /** Adds every link the locator matches, each `href` resolved against the document's base URL. */
289	  enqueueLinks<L extends Label<unknown, unknown>>(
290	    links: Locator,
291	    label: L,
292	    ...args: LinkPayloadArgs<L, EnqueueLinksOptions>
293	  ): Promise<EnqueuedLinks>;
294	  /** Ends the request `skipped`, with the reason `handler` and this message. Throws to unwind the handler. */
295	  skip(message: string): never;
296	  /** Ends this attempt with `retry_requested`, retried under `crawl.retry.max`. Throws to unwind the handler. */
297	  retry(message: string): never;
298	}
