const LOGIN_URL = 'https://quotes.toscrape.com/login';
const USERNAME = 'your-username';
const PASSWORD = process.env.QUOTES_TOSCRAPE_PASSWORD || 'default-password';
const STATE_NAME = 'quotes-toscrape-login-state';

// Function to log in and save the state
async function loginAndSaveState() {
  const foxhound = await Foxhound.connect();
  const page = await foxhound.start();

  await page.goto(LOGIN_URL);
  await page.fill('#username', USERNAME);
  await page.fill('#password', PASSWORD);

  // Wait for user to press Login
  console.log('Please press Login on the page...');
